#include "VersionedRecovery.h"
#include <chrono>
using namespace recovery;
int main(){auto root=fs::temp_directory_path()/("lg-version-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directory(root);try{auto src=root/"source";{std::ofstream o(src);o<<"first";}auto a=versionBackup(src,root,"001");{std::ofstream o(src);o<<"second";}auto b=versionBackup(src,root,"002");require(a!=b,"distinct versions");require(versionVerify(root,"001",a)==a,"first version");require(versionRestore(root,"002",root/"restored",b)==b,"restore");auto reject=[](auto f){bool failed=false;try{f();}catch(...){failed=true;}require(failed,"expected refusal");};reject([&]{versionBackup(src,root,"001");});reject([&]{versionVerify(root,"../bad",a);});reject([&]{versionVerify(root,"002",a);});reject([&]{versionRestore(root,"002",root/"restored",b);});{std::ofstream o(root/"generation-001"/"payload.bin");o<<"tampered";}reject([&]{versionVerify(root,"001",a);});fs::remove_all(root);return 0;}catch(...){fs::remove_all(root);throw;}}
